window.KT_AGE = {"zh": {"note": "年龄怎样变成设计。age-bands.json 说每个年龄段“怎么做”；这个文件说“为什么这样做、具体变的是哪个量、变在哪一层、拿什么来检验”。每一条走同一条链：学习科学里的一个概念 → 我们怎么理解它（以及理解的边界）→ 变成哪些设计变量、三个年龄段各取什么值 → 这些变量落在知识点、课程方案还是练习页面 → 记录什么来判断做对了没有。年龄界线是约定：识字情况、目标和已有水平优先于年龄。这里的取值是设计起点，没有在本项目的学习者身上验证过。", "layers": [{"id": "kc", "label": "知识点", "stays": "语言事实本身不随年龄变：同一个知识点 id、同样的形式和例句、同样的先修关系。", "changes": "哪些知识点进这门课、先后顺序、讲解里用不用术语、掌握证据取哪一种（听懂并做对、说出来、写出来）。", "where": "curriculum/\u003c语言>/tracks.json（每个年龄的方案只挑选和重排知识点）；kcs.json 的 mastery 从识别到产出分级，年龄决定先要到哪一级。"}, {"id": "plan", "label": "课程方案", "stays": "先修关系和来源覆盖：方案不能跳过必需的先修知识点。", "changes": "一次练多久、一周引入多少新内容、留多少时间回访、每个知识点预计花多久、谁陪着学、从哪里取材料。", "where": "本文件的 planDefaults（规划器按年龄段取这些数，写进蓝图的 assumptions）；blueprint/planner.js。"}, {"id": "block", "label": "练习页面", "stays": "教学原语的契约：学习者要做的那件事、检查什么、证据怎么记（第一次作答、有没有帮助、自评不算对）。", "changes": "任务由声音还是文字给出、一屏放多少、规则说不说和什么时候说、反馈怎么措辞、图和文字各占多少、顺序谁定、记录给谁看。", "where": "age-bands.json 的 variants（56 种原语 × 3 个年龄段）；支持 ?band= 的页面在本文件 blocks 里逐个写明它变了哪些量。"}], "planDefaults": {"note": "规划用的假设，不是实测的学习时间。规划器按年龄段取值；用起来以后按学习者的实际表现改。", "child": {"sessionMinutes": 15, "minutesPerKc": 25, "reviewShare": 0.3, "newPerSession": "一个语块或 3–5 个词"}, "youth": {"sessionMinutes": 30, "minutesPerKc": 30, "reviewShare": 0.25, "newPerSession": "一个知识点"}, "adult": {"sessionMinutes": 30, "minutesPerKc": 30, "reviewShare": 0.2, "newPerSession": "一到两个知识点"}}, "constructs": [{"id": "rules", "label": "规则：说不说、什么时候说", "question": "这条语言规律要不要讲出来？在例子之前还是之后？", "answer": {"child": "不讲，用成对的例子", "youth": "先做，再自己说出规律", "adult": "可以先看，带母语对照"}, "construct": {"claim": "年幼的学习者主要靠大量接触内隐地学会规律，这条路慢，需要很多输入；年长的学习者能从明示的规则里更快得到初期的准确度，但明示知识不会自动变成流利使用。", "understood": "我们把它读成一个时机和措辞的问题，而不是“孩子不教语法、成人只教语法”。所有年龄都先有例子；差别在于规律由谁说出来、用什么话、在哪一步。", "limits": "研究多来自课堂和实验室的短期比较；“内隐学习能力随年龄下降”的幅度有争议。8–12 岁已经能用一句大白话的规律。", "basis": "literature", "refs": ["ped:age-implicit-explicit", "ped:explicit-implicit-knowledge", "ped:explicit-instruction"]}, "variables": [{"id": "ruleTiming", "label": "规律什么时候出现", "layer": "block", "values": {"child": "不单独出现；用成对的例子让差别自己显出来。8–12 岁在做对几次之后给一句大白话。", "youth": "先做几个例子，让学习者自己说出规律，再给出准确说法。", "adult": "可以一开始就看，或随时点开；默认折叠，做题时不挡着。"}}, {"id": "metalanguage", "label": "用不用术语", "layer": "kc", "values": {"child": "不用术语，用“这个”“那样说”和颜色、位置来指。", "youth": "用少量学校里已经学过的术语，第一次出现时带一个例子。", "adult": "用通行的术语，并和学习者的母语对照一句。"}}], "measures": [{"label": "不给规律时在新例子上第一次就做对的比例", "source": "block", "how": "反向一半和迁移题的 attempt 事件里 first=true 且 assisted=false 的比例。", "reads": "高：规律能用了，不只是记住了讲解。看过规律才对的题记为有帮助，不算在内。"}, {"label": "点开规律的次数和时机", "source": "block", "how": "hint / reveal 事件，带题号。", "reads": "成人每题都先点开：规律还没内化，或题太难。儿童版没有这个按钮，不适用。"}]}, {"id": "text-channel", "label": "文字能不能用来传达任务", "question": "学习者读得懂屏幕上的指令吗？任务该用声音、示范还是文字给出？", "answer": {"child": "用声音和示范", "youth": "一两句文字", "adult": "文字；新文字用母语讲解"}, "construct": {"claim": "阅读理解约等于解码乘以语言理解：两样里缺一样就读不懂。还在学解码的人，不能靠读文字来学新东西。", "understood": "这条不只管儿童。5–7 岁在母语里也还在学解码；成人学一种新文字（汉字、假名）时，在目的语里同样是“还不会读”。所以分两件事判断：用来讲解的语言他读得懂吗；目的语的文字他读得出吗。", "limits": "简单阅读观是对母语阅读提出的模型，用在第二语言和非拼音文字上是推广。", "basis": "literature", "refs": ["ped:simple-view-of-reading", "ped:learning-to-read-vs-reading-to-learn", "ped:young-learner-characteristics"]}, "variables": [{"id": "instructionChannel", "label": "任务怎么给出", "layer": "block", "values": {"child": "5–7 岁：声音加示范，屏幕上不放说明文字。8–12 岁：一行短文字，可以点来听。", "youth": "文字，一两句；说明这一步练什么。", "adult": "文字；目的语的文字不熟时，讲解用母语或学习者选的讲解语言。"}}, {"id": "scriptAid", "label": "注音等读音辅助", "layer": "block", "values": {"child": "只用在已经会说的词上；一个词读对两次再撤。", "youth": "默认显示，按词撤除，学习者能看到自己撤了多少。", "adult": "默认隐藏、点开才看（点开记为有帮助），由学习者自己决定什么时候不再点。"}}], "measures": [{"label": "没有读音辅助时第一次读对的比例", "source": "block", "how": "attempt 事件按“辅助是否显示”分开统计。", "reads": "辅助一直开着时的正确率不能说明会读。"}, {"label": "听了才做对的题", "source": "block", "how": "先点了朗读再作答的题记为 assisted。", "reads": "多：是听懂的，不是读懂的。这在学认字阶段是正常的，要分开看。"}]}, {"id": "load", "label": "一次放多少、练多久", "question": "一屏放几样东西？一轮几题？一次练多久？", "answer": {"child": "一屏一件事，10–15 分钟", "youth": "一屏一个任务，20–30 分钟", "adult": "按时间盒，5–30 分钟"}, "construct": {"claim": "同时能留意的东西有限；年幼的学习者持续专注的时间更短，更容易被与任务无关的东西带走。", "understood": "我们把它落成三个可以数的量：一屏上要学习者处理的东西有几样、一轮几题、一次多少分钟。具体数字是设计推断，文献只支持方向（小的更少、更短）。", "limits": "分钟数和题数没有可以直接引用的标准，这里的数是起点。", "basis": "design_inference", "refs": ["ped:attention", "ped:young-learner-characteristics", "ped:seductive-details"]}, "variables": [{"id": "perScreen", "label": "一屏的量", "layer": "block", "values": {"child": "一屏一件事：一张图或一句话，一个要按的地方。", "youth": "一屏一个任务，材料和题目可以并排。", "adult": "可以一屏看到材料、题目和记录；次要的收起来。"}}, {"id": "roundSize", "label": "一轮几题", "layer": "block", "values": {"child": "3–6 题，结束有一个明确的“做完了”。", "youth": "6–10 题，或由学习者选几题。", "adult": "按时间盒：5 分钟或 15 分钟，题数随之而定。"}}, {"id": "sessionMinutes", "label": "一次多久", "layer": "plan", "values": {"child": "10–15 分钟，切成 3–5 个小活动，动静交替。", "youth": "20–30 分钟，一两个任务。", "adult": "5–30 分钟，按学习者每天能拿出的时间切块。"}}, {"id": "stepsPerItem", "label": "一题分几步、要不要说理由", "layer": "block", "values": {"child": "一题一步：只做选择，不问理由。", "youth": "两三步：先选，再说依据。", "adult": "两三步，包括“为什么”和排除别的选项的理由。"}}, {"id": "optionCount", "label": "一次几个选项", "layer": "block", "values": {"child": "2–3 个。", "youth": "3–4 个。", "adult": "4 个或更多，包括“都不是”“两个都行”。"}}], "measures": [{"label": "一轮里正确率有没有往下掉", "source": "block", "how": "同一轮前半和后半的第一次正确率。", "reads": "后半明显更低：这一轮太长了，先减题。"}, {"label": "一次练习做完的比例和实际时长", "source": "host", "how": "页面不记时长；由承载它的 app 记录开始、结束和中途离开。", "reads": "常常做不完：一次安排得太长。"}]}, {"id": "pace", "label": "进度和回访", "question": "一周引入多少新内容？隔多久再回来？", "answer": {"child": "新内容少，回访占三成", "youth": "回访占两成半", "adult": "新内容可以密，回访两成"}, "construct": {"claim": "在课堂条件下，年长的学习者起步更快；年幼的学习者进展慢，优势要靠多年、大量的接触才显出来。隔开时间重复提取，记得更牢。", "understood": "所以儿童方案不是“同样的内容讲得可爱一点”，而是每周新内容更少、回访更多、同一内容换着活动出现。成人方案新内容可以密一些，但回访不能省。", "limits": "每个知识点多少分钟、回访占几成，都是规划假设，没有实测。", "basis": "literature", "refs": ["ped:age-rate-vs-attainment", "ped:age-instructed-settings", "ped:spaced-practice", "ped:retrieval-practice"]}, "variables": [{"id": "minutesPerKc", "label": "每个知识点预计多久", "layer": "plan", "values": {"child": "约 25 分钟，分在几天里；内容更小块（一个语块、几个词）。", "youth": "约 30 分钟。", "adult": "约 30 分钟。"}}, {"id": "reviewShare", "label": "回访占一周的多少", "layer": "plan", "values": {"child": "三成：旧内容在新活动里再出现。", "youth": "两成半。", "adult": "两成，间隔逐步拉长。"}}, {"id": "selection", "label": "选哪些知识点", "layer": "kc", "values": {"child": "方案只选能在具体情境里听、说、做的；抽象语法和长篇读写往后放。", "youth": "和学校课程、考试、同龄人话题对得上的优先。", "adult": "学习者自己要用的场合优先（出行、工作、家庭），其余按先修关系补齐。"}}], "measures": [{"label": "隔几天之后第一次就做对的比例", "source": "host", "how": "app 按日期保存每个知识点的证据；回访时的第一次作答单独统计。", "reads": "当天会、隔几天不会：回访太少或间隔太长。页面自己不跨天保存。"}, {"label": "计划周数和实际周数的差", "source": "host", "how": "蓝图里的 agenda 对比实际完成日期。", "reads": "差得多：minutesPerKc 这个假设要改。"}]}, {"id": "feedback", "label": "反馈怎么给", "question": "答错之后页面说什么？对错记录给谁看？", "answer": {"child": "让他看出差别，再试；不打叉", "youth": "指出错在哪，再试", "adult": "说出错误类别，可跳过"}, "construct": {"claim": "纠正性反馈有用；明示的反馈（指出错在哪）比只给正确答案更容易被注意到，但要学习者有再试一次的机会才起作用。", "understood": "各年龄都是：马上、具体、再给一次机会。差别在于说到多细（指出这一下哪里不一样，还是说出错误的类别），以及记录的读者是谁。", "limits": "反馈研究多以青少年和成人为对象；儿童部分的做法是设计推断。", "basis": "design_inference", "refs": ["ped:corrective-feedback", "ped:noticing-hypothesis"]}, "variables": [{"id": "feedbackForm", "label": "答错时说什么", "layer": "block", "values": {"child": "把对的和选的放在一起让他看或听出差别，立刻再试；不出红叉、不扣分。", "youth": "指出错在哪一处，说一句原因，再试；不和别人比较。", "adult": "说出错误属于哪一类，可以连到规则；允许跳过，稍后再回来。"}}, {"id": "recordAudience", "label": "记录给谁看", "layer": "block", "values": {"child": "给陪着的大人看，不给孩子看分数。", "youth": "只给本人看；给老师看之前先让本人知道。", "adult": "给本人看，分类列出哪类题还不稳。"}}, {"id": "helpAvailable", "label": "能用哪些帮助", "layer": "block", "values": {"child": "帮助少而固定：重听一两次；没有计时。", "youth": "提示可以点开，点了记为有帮助。", "adult": "提示、慢速、字幕都可以自己开，用了记为有帮助。"}}], "measures": [{"label": "第一次错、第二次对的比例", "source": "block", "how": "同一题的第一次和后续 attempt。", "reads": "高：反馈被用上了。再试仍错：反馈没说到点上，或题超出了当前水平。"}, {"label": "提示之后才对的比例", "source": "block", "how": "assisted=true 的正确作答。", "reads": "这类不算独立掌握；长期偏高说明该退一步。"}]}, {"id": "autonomy", "label": "谁来决定、为什么学", "question": "顺序和目标由谁定？要不要说明这一步是为了什么？", "answer": {"child": "两三个里选一个，顺序固定", "youth": "顺序自己定，说明目的", "adult": "自己定目标和节奏"}, "construct": {"claim": "青少年对被控制敏感，有选择、知道目的时更愿意投入；成人带着自己的目标和经验来学，希望自己安排，并且要马上用得上。", "understood": "选择的范围随年龄放开：儿童在两三个里选一个，顺序由课程和大人把握；青少年可以自己排顺序，每一步写明目的；成人自己定目标和节奏，页面给建议而不是规定。", "limits": "成人教育学的这些假设主要来自经验总结，实证支持不如前几条。", "basis": "literature", "refs": ["ped:adolescent-motivation-autonomy", "ped:andragogy", "ped:scaffolding"]}, "variables": [{"id": "choice", "label": "能选什么", "layer": "block", "values": {"child": "在两三个主题或角色里选一个；步骤顺序固定，一步一步来。", "youth": "步骤可以任意顺序做；可以选题量。", "adult": "自己选做哪几步、做多久；可以直接跳到没把握的部分。"}}, {"id": "purposeLine", "label": "说不说这一步为了什么", "layer": "block", "values": {"child": "不讲目的，用故事里的任务带着走。", "youth": "每一步一句“这一步练什么”。", "adult": "每一步写明练的是哪项能力，以及在真实场合哪里用得上。"}}, {"id": "goalOwner", "label": "目标谁定", "layer": "plan", "values": {"child": "家长或老师定，方案里写明给大人看的目标。", "youth": "和学习者商量着定，对得上学校的要求。", "adult": "学习者自己定；先做自评，从没把握的地方开始。"}}], "measures": [{"label": "学习者选了哪个顺序、跳过了什么", "source": "block", "how": "步骤切换事件。", "reads": "总跳过同一步：这一步对他没用，或者太难。只是记录，不扣分。"}, {"label": "隔天还回不回来", "source": "host", "how": "由 app 记录；页面不知道。", "reads": "动机的间接信号，原因要问学习者本人。"}]}, {"id": "mediation", "label": "谁陪着学、谁来判断", "question": "旁边需要有人吗？口头说的话由谁判断对不对？", "answer": {"child": "大人陪着，大人判断", "youth": "同伴一起，同伴判断", "adult": "自己做，自己对照清单"}, "construct": {"claim": "有人在旁边提问、接话、把孩子的话说完整，孩子的语言长得更好（对话式共读）；支架要在学习者能自己做的时候撤掉。", "understood": "页面不听也不给发音打分，所以凡是开口说的部分都要有一个人来判断：儿童是陪着的大人，青少年是同伴，成人是自己或语伴。这些判断一律记为自评，不算答对。", "limits": "对话式共读的证据来自学龄前儿童的母语共读；用到第二语言和大孩子身上是推广。", "basis": "literature", "refs": ["ped:dialogic-reading", "ped:scaffolding", "ped:zpd", "ped:negotiated-interaction"]}, "variables": [{"id": "alongside", "label": "谁在旁边", "layer": "plan", "values": {"child": "家长或老师；页面给大人一句可以照着说的话。", "youth": "同学两两一组，或自己做完再和同伴交换。", "adult": "自己；可以找语伴，页面不依赖有人在。"}}, {"id": "oralJudge", "label": "说出来的话谁判断", "layer": "block", "values": {"child": "大人点“说到了 / 还没有”。", "youth": "同伴对照清单勾选。", "adult": "自己对照清单或录音回听。"}}], "measures": [{"label": "自评或他评的结果", "source": "block", "how": "selfReport 事件，和作答分开存。", "reads": "只说明“有人认为说到了”，不能当作掌握的证据；同伴之间容易手下留情。"}]}, {"id": "picture", "label": "图、声音、动作各做什么", "question": "图是用来带出意思的，还是只在文字说不清时才出现？", "answer": {"child": "图是主体，文字很短", "youth": "图文并排", "adult": "图只在文字说不清时出现"}, "construct": {"claim": "词语配上相关的图比只有词语学得好；与要学的内容无关的有趣细节会降低学习效果；动作和手势帮助记住词义。", "understood": "图不是装饰，每张图有一个教学用途（image-roles.json 里的八种）。年龄越小，图和声音承担的越多；年龄越大，图越退到“文字说不清的地方”。无论哪个年龄，图里都不放与任务无关的东西。", "limits": "多媒体学习的研究多以大学生学科学内容为对象；用到儿童语言学习上是推广。", "basis": "literature", "refs": ["ped:multimedia-learning", "ped:dual-coding", "ped:picture-superiority-vocabulary", "ped:seductive-details", "ped:embodied-gesture-learning", "ped:total-physical-response"]}, "variables": [{"id": "pictureShare", "label": "图占多少、放在哪", "layer": "block", "values": {"child": "图是主体，占画面大半，文字在图的正下方、很短。", "youth": "图和文字并排，图不超过一半，可以编号对应。", "adult": "图只出现在文字说不清的地方，放在相关句子旁边，可以点开放大。"}}, {"id": "movement", "label": "用不用身体动作", "layer": "block", "values": {"child": "听了就做：站起来、指、拿，由大人看着。", "youth": "在屏幕上拖、摆、标；真的动起来只在小组活动里。", "adult": "在屏幕上操作；动作用在方位、手势这类本来就和身体有关的内容上。"}}], "measures": [{"label": "去掉图之后还能不能做对", "source": "block", "how": "反向一半：同样的词放进没有图的新句子里，统计第一次正确率。", "reads": "有图会、没图不会：认的是图，不是词。"}, {"label": "生成的图是否通过验收清单", "source": "host", "how": "图片指令附带的 acceptance 清单，由人逐条核对。", "reads": "有一条不过就不用这张图。"}]}, {"id": "reading-mode", "label": "学习阅读，还是通过阅读学习", "question": "这次阅读的目标是学会读这种文字，还是借着读来学新的语言？", "answer": {"child": "绘本，大人陪着指读", "youth": "贴近同龄人的图文故事", "adult": "真实生活里的图文"}, "construct": {"claim": "阅读的发展分两段：先学会把文字变成已经会说的话，之后才用阅读去学还不会的东西。第二语言读者要到一定的语言水平，母语里的阅读本领才用得上。", "understood": "哪一种读法由两个问题决定，不由年龄决定：这段话听得懂吗？这种文字自己读得出吗？听得懂但读不出，是学习阅读；读得出，是通过阅读学习。两种读法每个年龄都有：成人学汉字、学假名时是在学习阅读，十岁的孩子读英语分级读物可以是通过阅读学习。年龄改变的是读物的题材和样子、大人在不在、进度怎么显示。", "limits": "两段论来自母语阅读发展研究；门槛在哪里没有统一的数字。", "basis": "literature", "refs": ["ped:learning-to-read-vs-reading-to-learn", "ped:simple-view-of-reading", "ped:l2-reading-threshold", "ped:extensive-reading", "ped:dialogic-reading"]}, "variables": [{"id": "material", "label": "读什么", "layer": "plan", "values": {"child": "绘本：图讲故事，文字很短、重复多。", "youth": "题材贴近同龄人的短故事或图文，画风不低幼。", "adult": "真实生活里的图文：告示、时刻表、带图的说明、短报道。"}}, {"id": "readingPace", "label": "学习阅读时的节奏", "layer": "block", "values": {"child": "一页一句，大人陪着指读；同一本书读好几遍。", "youth": "自己读，逐词撤辅助；能看到哪些词已经不用辅助。", "adult": "先看规律（偏旁、拼写规则），再在真实文字上认；按时间盒练。"}}, {"id": "progressDisplay", "label": "进度怎么显示", "layer": "block", "values": {"child": "读到第几页；不显示正确率。", "youth": "学习阅读：多少个词已经不用辅助。通过阅读学习：猜对了几个生词、靠的是什么线索。", "adult": "同青少年，另加按错误类别的汇总。"}}], "measures": [{"label": "学习阅读：无辅助、无图时读对的词数", "source": "block", "how": "撤掉辅助之后、反向一半里的第一次正确作答。", "reads": "这才算“会读这个词”。"}, {"label": "通过阅读学习：生词猜测对不对、靠什么线索", "source": "block", "how": "猜词题的 attempt 加线索选择；页面解释不了的词，答“这里看不出来”才算对。", "reads": "能分清“看得出来”和“看不出来”，比猜对几个更重要。"}]}, {"id": "use-context", "label": "材料从哪来、学了在哪用", "question": "例子和情境取自谁的生活？学到的东西第一次用在哪里？", "answer": {"child": "游戏、家里、故事", "youth": "同学、学校、爱好", "adult": "自己马上要办的事"}, "construct": {"claim": "学到的东西迁移到新场合并不自动发生，练习的情境越接近将来要用的情境越容易迁移。成人学习者时间少、目标具体，母语已经定型，会不自觉地拿母语来对照。", "understood": "同一个知识点，三个年龄段的例句情境不同：儿童取自游戏、家里和故事；青少年取自同伴、学校和他们看的东西；成人取自自己马上要办的事。成人还多一个量：和母语的对照，说清哪里一样、哪里会被母语带偏。", "limits": "情境的选择是设计推断；“成人受母语影响更大”有文献支持，但因语言对而异。", "basis": "design_inference", "refs": ["ped:transfer", "ped:adult-l2-constraints", "ped:andragogy", "ped:young-learner-characteristics"]}, "variables": [{"id": "exampleContext", "label": "例子的情境", "layer": "kc", "values": {"child": "游戏、家里、动物、故事里的角色。", "youth": "同学、学校、爱好、短视频和游戏里会遇到的话。", "adult": "出行、工作、看病、租房等学习者自己说要用的场合。"}}, {"id": "l1Compare", "label": "和母语对照", "layer": "block", "values": {"child": "不对照；传承语儿童已经会的部分不重复练。", "youth": "点明一处最容易被母语带偏的地方。", "adult": "规律旁边固定有一句和母语的对照。"}}], "measures": [{"label": "换了情境的迁移题第一次就对的比例", "source": "block", "how": "迁移题和原题分开统计。", "reads": "原题会、迁移题不会：只是记住了这几个例子。"}, {"label": "学习者说在真实场合用上了没有", "source": "host", "how": "由 app 隔几天问一次；是自评。", "reads": "只是自评，不能当作掌握的证据。"}]}], "blocks": {"picture-book": {"summary": "两种读法每个年龄都能用。儿童读绘本；青少年和成人读另一本不低幼、画面里有真实文字的故事。年龄改变的是读物、陪伴、规律什么时候出现、谁定目标和记录怎么写。", "rows": [{"variable": "material", "child": "绘本《蓝色的纸船》，8 页。", "youth": "图文故事《末班车之后》，7 页，画面里有真实的文字（站牌、时刻表、店门告示）。", "adult": "同一本《末班车之后》。"}, {"variable": "instructionChannel", "child": "每一步的说明可以点来听；另有一栏给陪着的大人照着说的话。", "youth": "文字说明，加一句“这一步为什么”。", "adult": "文字说明，写明这一步练什么、为什么放在这里。"}, {"variable": "choice", "child": "一次一步，按顺序走。", "youth": "步骤顺序自己定。", "adult": "自己定这个单元的目标，选 5、10 或 15 分钟的时间盒；时间到了有提示，不拦着。"}, {"variable": "ruleTiming", "child": "不显示规律。", "youth": "答完之后才看到，标题是“你刚才用到的规律”。", "adult": "答题之前就能看到规律，不算提示；“拆开看”的提示仍算帮助。"}, {"variable": "l1Compare", "child": "没有。", "youth": "没有。", "adult": "每个目标词的规律旁有一句和母语的对照。"}, {"variable": "scriptAid", "child": "注音先显示，一个词无辅助读对两轮才撤，读错就恢复。", "youth": "同样的撤除规则，旁边列出“已经不用辅助的词”。", "adult": "同样的撤除规则；点开看注音记为有帮助。"}, {"variable": "oralJudge", "child": "看图说和复述由陪着的大人判断。", "youth": "每一步有“和同学一起”的做法；复述对照清单自评。", "adult": "复述对照清单自评。"}, {"variable": "recordAudience", "child": "记录收在“给大人看的记录”里，不给孩子看。", "youth": "记录栏就在步骤旁边。", "adult": "记录按任务写成“这个单元做成了什么”，带目标和用掉的时间。"}]}, "space-3d": {"summary": "同一类题（这／那、来／去、前后左右怎样随视角变）；年龄改变的是题目和题量、每题几步、规律什么时候出现、反馈用不用术语，以及“自己摆”那一步由谁判断。", "rows": [{"variable": "roundSize", "child": "这儿／那儿 4 题，来／去 3 题，前后左右 4 题。", "youth": "7 题、5 题、7 题。", "adult": "7 题、5 题、7 题（中文包的来／去是 4 题）。"}, {"variable": "exampleContext", "child": "小熊和小兔；苹果、球、树、蛋糕。", "youth": "两个同龄人和家人；手机、杯子、海报、宣传册、雨伞、旅行。", "adult": "同样的人物；另有文件、聚会邀请（英语、日语包）、酒店和出租车。"}, {"variable": "selection", "child": "前后左右只出一种说法通的情形（小熊的前面、树的前面和后面）。", "youth": "包括“车的前边／左边”这种两种说法都通的情形。", "adult": "同青少年，另有只按自身方向说的“酒店门口”等。"}, {"variable": "ruleTiming", "child": "不显示规则栏；旁边是“给陪着的大人”。", "youth": "规则栏先空着，这一种题答过第一次后才出现；前后左右另有一句“两种参照”的说明。", "adult": "规则栏一开始就显示。"}, {"variable": "l1Compare", "child": "没有。", "youth": "没有。", "adult": "规则下面有一句写在语言包里的对照（中文包对照英语和日语，英语包对照汉语）。"}, {"variable": "instructionChannel", "child": "每题出现后自动读一遍问题，每个选项旁有一个喇叭图标的朗读按钮；题目文字仍在屏幕上。另有一栏给陪着的大人。", "youth": "文字；不自动朗读。", "adult": "文字；不自动朗读。"}, {"variable": "perScreen", "child": "每题一步：直接选词，或点编号把球放过去。换人说时直接再选一次。", "youth": "每题两三步：先点出说话的是谁，再选词；换人说时先答“要变／不用变／两种都可以”；球放对后追问“别的编号有没有可能也对”。", "adult": "同青少年。"}, {"variable": "feedbackForm", "child": "一句短话，不用术语（“看看小熊的脸朝哪边。”）；没有提示按钮。", "youth": "说明这句话按谁的方向说，用“相对参照”“固有参照”；有两到三级提示，用了记为辅助。", "adult": "同青少年。"}, {"variable": "movement", "child": "只在前后左右：提示大人让孩子站起来、转身，先用身体做一遍；屏幕上只有一个“当小熊”的大按钮。", "youth": "在屏幕上转动场景、换到每个人的眼睛看。", "adult": "在屏幕上转动场景、换到每个人的眼睛看。"}, {"variable": "oralJudge", "child": "“自己摆”：孩子摆好后口头说，大人点“说对了／还没有”，记为大人判断。", "youth": "“自己摆”：写一句，页面对照场景检查；写对后可以“交给同伴”，同伴照句子摆，页面比对，记为同伴判断。没有口头的一步。", "adult": "“自己摆”：写两句（两种情形各一句），页面对照场景检查。没有别人判断的一步。"}, {"variable": "pictureShare", "child": "场景高 440 像素。", "youth": "场景高 380 像素。", "adult": "场景高 320 像素。"}, {"variable": "recordAudience", "child": "三种题的记录收在一个默认折叠的“给陪着的大人的记录”里，孩子看不到分数。", "youth": "“三种分开记”卡片直接显示在旁边。", "adult": "“三种分开记”卡片直接显示在旁边。"}]}, "blend": {"summary": "同样的词和拼读规则；儿童版每轮更短、选项更少，拼词从“整词摆出来”变成“补一格”。", "rows": [{"variable": "roundSize", "child": "每轮 5 题；“规则外”3 个例外词加 3 个规则词。", "default": "每轮 8 题；“规则外”5 加 5。"}, {"variable": "perScreen", "child": "读词给 3 张图选；拼词只空一格，从 3 个字块里点一个，点了就判。", "default": "读词给 4 张图选；拼词要从一排字块里把整个词摆出来，再点“摆好了”。"}, {"variable": "instructionChannel", "child": "一句短文字（“点一点，读一读，是哪个？”）；页面不把说明读出来。", "default": "一两句文字，说明先做什么再做什么。"}, {"variable": "feedbackForm", "child": "拼词只有“一格一格放”一个提示；没有“看答案”和“清空”。", "default": "拼词有两级提示（几格、难点格）、“看答案”和“清空”。"}, {"variable": "scriptAid", "child": "点格子时不显示音标；每格放 1.3 秒。", "default": "点格子时显示音标；每格放 1 秒。"}]}, "classifier-match": {"summary": "儿童版只用一组东西、最多 3 个盒子，不问“这个盒子里的东西有什么共同点”，新词也不出例外。", "rows": [{"variable": "roundSize", "child": "分类：标了儿童的那一组，最多 3 个盒子；新词 5 个。", "default": "分类：两组轮流，盒子全用（2–5 个）；新词 8 个。"}, {"variable": "ruleTiming", "child": "不出现“每个盒子的共同点”这一步，放完就结束。", "default": "全部放好以后，要给每个盒子选一个共同点。"}, {"variable": "perScreen", "child": "新词只出按规律能推的词，没有例外、两可、都不行的题。", "default": "新词每轮至少四分之一是例外、两可或都不行的题。"}, {"variable": "instructionChannel", "child": "一句短文字：“点一样东西，再点它该去的篮子。”", "default": "一句文字，另说明可以按盒子编号。"}]}, "culture-incident": {"summary": "儿童版只有一个发生在同学之间的事件，原因只分三类，并且这一步记为讨论，不算对错。", "rows": [{"variable": "exampleContext", "child": "每个语言包 1 个事件，发生在课间、同学或老师之间（饼干、橡皮、怎么称呼老师）。", "default": "每个语言包 6–7 个事件：成年人的日常和工作场合。"}, {"variable": "metalanguage", "child": "原因三选一：“说的话”“说话的样子”“其实没问题”。", "default": "原因五选一：说法本身、礼貌程度或称呼、话题或时机、没听出言外之意、其实没有文化误会。"}, {"variable": "oralJudge", "child": "选原因这一步记为自评（讨论），不和第 1 步点的句子挂钩。", "default": "选原因由页面判对错，第 1 步点错句子就不算对。"}, {"variable": "instructionChannel", "child": "一句短文字：“从哪一句开始，有人不太舒服了？点那一句。”点了就算作答，不用写解释，也没有提交按钮。", "default": "文字：点出那一句，再写一句解释，提交后锁定。"}]}, "entry-sense-pick": {"summary": "儿童版只选义项，不用说排除理由和线索词，每轮 4 句，不出两个义项都通或固定短语的句子。", "rows": [{"variable": "roundSize", "child": "查词 4 句；记进生词本 3 条。", "default": "查词 8 句；记进生词本 5 条。"}, {"variable": "perScreen", "child": "每句只做一件事：点一个义项。", "default": "每句三件事：选义项、给每个没选的义项一个排除理由、点出原句里的线索词。"}, {"variable": "ruleTiming", "child": "不出“两个义项都说得通”和“固定短语”的句子。", "default": "每轮固定有一句两个义项都通的、一句固定短语的。"}]}, "exchange-script": {"summary": "儿童版只有一个课堂场景，结局用表情显示，回看时的分类用大白话。", "rows": [{"variable": "exampleContext", "child": "每个语言包 1 个场景，都在学校里（上课没听懂一个词、向同学借橡皮、早上到校）。", "default": "每个语言包 6 个场景：打电话改预约、点餐、投诉、婉拒邀请等。"}, {"variable": "feedbackForm", "child": "结局是两张表情：“事情办成了吗”“对方的心情”；通过时只说“成功了！”。", "default": "结局是两条刻度“目的”“关系”，带文字说明；通过时说明事情办成、关系没受损。"}, {"variable": "metalanguage", "child": "回看时四类：办成了对方也高兴、办成了可对方不太高兴、对方没听明白、说哪句都行。选项始终显示原话。", "default": "回看时五类（办成且合适、办成但对方不舒服、没办成、两样都没做到、换哪个都一样）；选项可以显示成这一句的功能名。"}]}, "false-friend-check": {"summary": "儿童版每轮 3 个词，标记用大白话，标“有点不一样”时不再追问偏在哪儿。", "rows": [{"variable": "roundSize", "child": "判断 3 个词；运用 3 题。", "default": "判断 9 个词；运用 6 题。"}, {"variable": "metalanguage", "child": "三个标记叫“一样 😀”“有点不一样 🤔”“完全不一样 😲”。", "default": "三个标记叫“相同”“偏移”“完全不同”。"}, {"variable": "perScreen", "child": "选了“有点不一样”就算判完。", "default": "选了“偏移”还要再选偏在哪儿（意思范围、褒贬色彩、语体、搭配），选了才算判完，并且计入对错。"}]}, "figurative-decode": {"summary": "儿童版（英语、中文包）换成另一种做法：先看照字面画出来的图，再选说话人真正想说的那张图；不出反语和暗示。", "rows": [{"variable": "pictureShare", "child": "每题一句话加一张“照字面画出来”的图，答案也是图（两张里选一张）。", "default": "没有图：读一小段文字，分三步写出字面意思、落差和真正的意思。"}, {"variable": "roundSize", "child": "英语 6 题、中文 5 题。", "default": "15–16 段。"}, {"variable": "selection", "child": "只有比喻、习语和字面句；三步解读里也去掉反语和暗示。", "default": "包括反语、讽刺和没明说的请求。"}, {"variable": "feedbackForm", "child": "选错时说“再听一遍，想一想：真的会这样吗？”，可以接着再选。", "default": "分步指出字面层和真正意思的落差。"}]}, "listen-and-do": {"summary": "儿童版只在房间场景里做 5 条简单指令，不出“别……”“如果……”这类题，最多重听两次，没有慢速和字幕。", "rows": [{"variable": "roundSize", "child": "每轮 5 条，只在“房间”场景。", "default": "房间 8 条，问路地图 6 条，两个场景可以换。"}, {"variable": "selection", "child": "只出简单指令（包里标了儿童的 6 条），没有“别／不要”“如果……”“男孩的左手”这类。", "default": "每轮至少 2 条这类“不是听到什么就动什么”的指令。"}, {"variable": "feedbackForm", "child": "可以重听 2 次；没有“慢速”和“字幕”。", "default": "重听不限次；有“慢速”和“字幕”，用了记为辅助。"}, {"variable": "instructionChannel", "child": "指令由语音读出；屏幕上的说明只有“听一听，做一做。”", "default": "指令由语音读出；屏幕上的说明讲清做完点“做好了”、这一步不显示对错。"}]}, "number-system-map": {"summary": "儿童版换成 5 张一万以内的数字卡，估大小只有 4 级。", "rows": [{"variable": "selection", "child": "5 张卡，数在一万以内，只有数字本身（三百、两千五百）。", "default": "15–16 张卡，数到亿，放在句子里（“这座小城有十五万人”）。"}, {"variable": "perScreen", "child": "估大小有 4 级可选：10+、100+、1,000+、10,000+。", "default": "估大小有 9 级可选：100+ 到 10,000,000,000+。"}]}, "oral-sound-play": {"summary": "儿童版每轮更短，“分一分”变成对一种关系回答是或不是。", "rows": [{"variable": "roundSize", "child": "拍一拍 5 个词；换一换 4 题；分一分 5 题。", "default": "拍一拍 8 个词；换一换 6 题；分一分 8 题。"}, {"variable": "perScreen", "child": "分一分只问一件事：“它们押韵吗？”（日语包：“拍数一样吗？”），答是或不是。", "default": "分一分要在几种关系里选，每轮有 2 题是“看着像、其实不是”的。"}, {"variable": "instructionChannel", "child": "一句短文字：“听一听，拍一拍。”页面不把说明读出来。", "default": "一句文字，说明拍的是音节还是音素。"}]}, "paradigm-apply": {"summary": "英语包的儿童版先做“怪物词”：孩子口头说，大人点孩子说了什么；日语、中文包只是运用题少 3 题。", "rows": [{"variable": "oralJudge", "child": "英语包：孩子把句子口头说完，大人点孩子说的是哪个，记为“搭档判断”。", "default": "学习者自己在屏幕上分组、填形式，页面判对错。"}, {"variable": "ruleTiming", "child": "英语包：不先看规则，直接用没听过的编造词（gutch → ？）试规则。", "default": "先把学过的词按“怎么变的”分组，自己归纳出规则，再运用。"}, {"variable": "roundSize", "child": "怪物词 4 题；运用 5 题。", "default": "运用 8 题（标准版没有怪物词标签页）。"}]}, "picture-talk": {"summary": "同一幅图，儿童版只用其中 6 样东西，描述改成口头说三句，判断只分对和不对。", "rows": [{"variable": "roundSize", "child": "图上只用 6 样（狗、猫、鸭子、小朋友、男孩、树）；听了指 9 题；判断 4 句；问答 4 题。", "default": "图上 14 样全用；听了指 16 题；判断 7 句；问答 9 题。"}, {"variable": "instructionChannel", "child": "描述这一步没有输入框：“看着图说三句话”，说完点“我说完了”。", "default": "描述这一步写 6 到 8 句，一行一句；也可以选“我是口头说的”。"}, {"variable": "oralJudge", "child": "口头说的页面听不到：之后由自己或搭档对着图核对。", "default": "写下来的句子由页面和图上的事实核对；口头说的同样由自己或搭档核对。"}, {"variable": "metalanguage", "child": "判断别人的描述只分“对”“不对”。", "default": "判断别人的描述要五选一：说得对、位置不对、数量不对、动作和状态弄混了、图上看不出来。"}]}, "reading-aid-fade": {"summary": "注音的撤除规则两版一样；儿童版只是读后抽查更少、更容易。", "rows": [{"variable": "roundSize", "child": "读完抽查 2 个词；错误分类 4 题。", "default": "读完抽查 4 个词；错误分类 8 题。"}, {"variable": "perScreen", "child": "抽查时每个词两个读音里选一个，不用打字。", "default": "抽查时在全部候选读音里选；语言包支持时要自己把读音打出来。"}]}, "reading-select": {"summary": "儿童版只选读音，不问“为什么这样读”。", "rows": [{"variable": "ruleTiming", "child": "不问依据：每一处只选读音。", "default": "每一处选读音，还要选依据（词性和意思、固定词语、量词、要单独记）；同一个字在两个语境里第一次就对以后才不再问。"}, {"variable": "roundSize", "child": "“换句子”5 题。", "default": "“换句子”把整组题做完。"}]}, "repair-and-backchannel": {"summary": "儿童版只有一段课堂对话，三种求助办法，点了办法页面就替你说出一句合适的话，不限时。", "rows": [{"variable": "exampleContext", "child": "每个语言包 1 段对话：跟着老师做手工（折纸船、用剪刀、用蜡笔）。", "default": "每个语言包 3 段：问询处买票、小组讨论、打电话等。"}, {"variable": "choice", "child": "3 个办法：请再说一遍、请说慢一点、问一个词；带图标。", "default": "8 个办法：另有复述确认、附和接话、争取时间、礼貌插话、把话题拉回来。"}, {"variable": "perScreen", "child": "点了办法，页面直接说出一句合适的话，不用自己挑怎么说。", "default": "点了办法以后，还要在几句说法里挑一句。"}, {"variable": "feedbackForm", "child": "不限时；没有“暂停”和“哪里没跟上”提示。", "default": "默认有回应时间窗口（可以关）；有“暂停”和“哪里没跟上”提示，用了记为辅助。"}]}, "role-marking": {"summary": "儿童版每轮 4 句，角色叫“谁”“在哪儿”“去哪儿”“和谁”，不追问为什么用这个标记。", "rows": [{"variable": "roundSize", "child": "每轮 4 题（包里标了儿童的只有 4 句）。", "default": "每轮 8 题，从 20 句左右里抽。"}, {"variable": "metalanguage", "child": "角色叫“谁”“在哪儿做”“去哪儿”“和谁”。", "default": "角色叫“做事的人”“在某处的人或物”“存在处”“到达点／终点”“同伴”等。"}, {"variable": "ruleTiming", "child": "标记选对就过，不问为什么。", "default": "标记都选对后，有的题还要答一个“为什么用这个标记”。"}, {"variable": "instructionChannel", "child": "一句短文字：“看图。每个东西是‘谁’‘在哪儿’‘去哪儿’还是‘和谁’？”", "default": "一两句文字：读句子、看图，判断每个编号的名词是什么角色。"}]}, "sound-contrast": {"summary": "英语包的儿童版用 5 对图卡：只看图不看字，每轮 6 题，答完不说对错、直接把两个词再放一遍；日语、中文包没有儿童内容。", "rows": [{"variable": "pictureShare", "child": "英语包：卡片上只有图（或数字），没有拼写和释义。", "default": "卡片上是词的拼写，有图时图在上面，可以带释义。"}, {"variable": "roundSize", "child": "听辨 6 题；归类 6 题。", "default": "听辨 12 题另加 3 题“一样不一样”；归类 9 题。"}, {"variable": "feedbackForm", "child": "答完不分对错，都是“是这个：（图）。再听一遍两个词。”，对的那张卡跳一跳，然后 A-B-A 连放。", "default": "答对说“对”，答错说“听到的是 X，不是 Y”并显示红色，两个词并排、标出不同的字母，然后 A-B-A 连放。"}, {"variable": "instructionChannel", "child": "一句短文字，旁边有“🔊 说明”按钮，点了用界面语言读出来。", "default": "一句文字，带键盘用法（F／J）。"}, {"variable": "ruleTiming", "child": "不显示这组对立的发音说明。", "default": "作答区旁边有这组对立的说明（舌位、母语里有没有这个音）。"}]}, "story-frames": {"summary": "同一个故事；儿童版押“故事接下来怎么走”只有两张卡，不问倒叙那一处，连接词和复述的要求都少一些。", "rows": [{"variable": "perScreen", "child": "押下一幅时两张方向卡：“然后……”“可是……”。", "default": "押下一幅时四张方向卡：另有“所以……／最后……”“原来，以前……”。"}, {"variable": "selection", "child": "不问“回头说以前的事”那一处；连接词只出先后、转折、补叙、收尾四类。", "default": "倒叙那一处也要押；连接词另有因果、同时和“用错”的干扰项。"}, {"variable": "roundSize", "child": "复述里用到 2 种衔接手段就够。", "default": "复述里要用到 3 种衔接手段。"}]}, "tone-contour": {"summary": "儿童版把声调叫作平路、上坡、山谷、下坡，不出半三声和轻声词，选项更少。", "rows": [{"variable": "metalanguage", "child": "声调叫“平路”“上坡”“山谷”“下坡”“小圆点”，答案按钮上不写调值数字。", "default": "声调叫“一声 55”“二声 35”，图例里有阴平、阳平、上声、去声的说明。"}, {"variable": "selection", "child": "不出半三声；听辨不出带轻声的词。", "default": "有半三声（只降不升）这一项；听辨包括轻声词。"}, {"variable": "perScreen", "child": "听单字 3 选 1，听词 4 个声调里选；日语音调 2 选 1。", "default": "听辨 5 选 1（四声加轻声）；变调题 5 个选项（含半三声）；日语音调列出全部可能的型。"}, {"variable": "pictureShare", "child": "大的调形图上不画五度刻度，线更粗。", "default": "大的调形图带 1–5 的五度刻度。"}]}, "variety-map": {"summary": "儿童版只把 6 张卡分到两种变体里，没有“都通用”和“其实是错的”这两列，也没有第三步。", "rows": [{"variable": "roundSize", "child": "每轮 6 张卡，两步（认出来、定场合）。", "default": "每轮 10 张卡，三步（另有“保持一致”）。"}, {"variable": "perScreen", "child": "只有各变体的列（如英式、美式）。", "default": "另有“各变体通用”和“不是变体，是错误”两列，每轮至少各有一张这样的卡。"}, {"variable": "instructionChannel", "child": "一句短文字：“点一张卡，再点它属于哪一边。”", "default": "两三句文字，说明卡上没有标签、有的说法通用、有的是错误。"}]}, "viewpoint-direction": {"summary": "儿童版只出家里和妈妈这类情境，每轮 2–3 题。", "rows": [{"variable": "roundSize", "child": "摆位置每轮 2–3 题（包里标了儿童的只有这么多）；换视点这一步跳过（包里没有标儿童的题），页面用一句话说明。", "default": "摆位置每轮 8 题；换视点 6 题。"}, {"variable": "exampleContext", "child": "情境是在家里等妈妈、和家人之间的事。", "default": "情境是学长、朋友等人之间的给予、来去和被动。"}, {"variable": "instructionChannel", "child": "一句短文字：“先把眼睛（我）放好，再画箭头，然后选一个词。”", "default": "一两句文字，说明箭头表示谁给谁、往哪儿移动、谁受了影响。"}]}}}, "en": {"note": "How age turns into design. age-bands.json says how to do things for each age band. This file says why, which quantity changes, at which layer it changes, and what to measure to check it. Every entry follows the same chain: one concept from the learning sciences, how we read it (and where that reading stops), which design variables it becomes and what value each of the three age bands gets, whether those variables sit in the knowledge point, the course plan or the practice page, and what to record to tell whether it worked. Age boundaries are a convention: how well the learner reads, their goals and their existing level come first. The values here are a starting point for design and have not been tested with this project's learners.", "layers": [{"id": "kc", "label": "Knowledge point", "stays": "The language facts do not change with age: the same knowledge point id, the same forms and example sentences, the same prerequisite links.", "changes": "Which knowledge points go into the course and in what order, whether explanations use technical terms, and which kind of mastery evidence is taken (understands and gets it right, says it, writes it).", "where": "curriculum/\u003clang>/tracks.json (each age's plan only selects and reorders knowledge points); the mastery field in kcs.json is graded from recognition to production, and age decides which level to reach first."}, {"id": "plan", "label": "Course plan", "stays": "Prerequisite links and source coverage: a plan may not skip a required prerequisite knowledge point.", "changes": "How long one session lasts, how much new content comes in each week, how much time is kept for revisiting, how long each knowledge point is expected to take, who studies alongside the learner, and where the material comes from.", "where": "planDefaults in this file (the planner takes these numbers by age band and writes them into the blueprint's assumptions); blueprint/planner.js."}, {"id": "block", "label": "Practice page", "stays": "The contract of the practice type: the one thing the learner does, what is checked, and how evidence is recorded (first attempt, whether help was used, self-report does not count as correct).", "changes": "Whether the task is given by sound or by text, how much goes on one screen, whether and when the rule is stated, how feedback is worded, how much space pictures and text each get, who decides the order, and who the record is for.", "where": "variants in age-bands.json (56 practice types x 3 age bands); for pages that support ?band=, the blocks section of this file says, page by page, which variables they change."}], "planDefaults": {"note": "Planning assumptions, not measured learning times. The planner takes the values by age band. Once the plan is in use, adjust them to how the learner actually performs.", "child": {"sessionMinutes": 15, "minutesPerKc": 25, "reviewShare": 0.3, "newPerSession": "one chunk or 3–5 words"}, "youth": {"sessionMinutes": 30, "minutesPerKc": 30, "reviewShare": 0.25, "newPerSession": "one knowledge point"}, "adult": {"sessionMinutes": 30, "minutesPerKc": 30, "reviewShare": 0.2, "newPerSession": "one or two knowledge points"}}, "constructs": [{"id": "rules", "label": "Rules: whether to state them, and when", "question": "Should this language pattern be stated outright? Before the examples or after?", "answer": {"child": "Not stated; paired examples", "youth": "Try first, then say the rule", "adult": "Rule up front, compared with L1"}, "construct": {"claim": "Young learners mostly pick up patterns implicitly through a lot of exposure. This route is slow and needs plenty of input. Older learners can get accurate faster at the start from explicit rules, but explicit knowledge does not turn into fluent use by itself.", "understood": "We read this as a question of timing and wording, not as 'children get no grammar and adults get only grammar'. Every age starts with examples. What differs is who states the pattern, in what words, and at which step.", "limits": "Most of the research is short-term comparisons in classrooms and labs. How much implicit learning ability declines with age is disputed. Children aged 8–12 can already use a pattern put in one plain sentence.", "basis": "literature", "refs": ["ped:age-implicit-explicit", "ped:explicit-implicit-knowledge", "ped:explicit-instruction"]}, "variables": [{"id": "ruleTiming", "label": "When the pattern appears", "layer": "block", "values": {"child": "It does not appear on its own; paired examples let the difference show itself. At 8–12, give one plain sentence after a few correct answers.", "youth": "Do a few examples first and let the learner say the pattern, then give the precise wording.", "adult": "It can be shown at the start or opened at any time; folded by default so it does not get in the way during exercises."}}, {"id": "metalanguage", "label": "Whether to use technical terms", "layer": "kc", "values": {"child": "No technical terms; point with 'this one', 'say it that way', colours and positions.", "youth": "A few terms already learned at school, each with an example the first time it appears.", "adult": "Standard terms, with one line comparing to the learner's first language."}}], "measures": [{"label": "Share of new examples answered correctly on the first try without the rule shown", "source": "block", "how": "The share of attempt events with first=true and assisted=false in the reverse half and in transfer items.", "reads": "High: the learner can use the pattern, not just remember the explanation. Items answered correctly only after viewing the rule count as assisted and are left out."}, {"label": "How often and when the rule is opened", "source": "block", "how": "hint / reveal events, with the item number.", "reads": "Adults who open it before every item: the pattern is not yet internalised, or the items are too hard. The child version has no such button, so this does not apply."}]}, {"id": "text-channel", "label": "Whether text can carry the task", "question": "Can the learner read the instructions on the screen? Should the task be given by sound, by demonstration or by text?", "answer": {"child": "Voice and demonstration", "youth": "A line or two of text", "adult": "Text; a new script is explained in L1"}, "construct": {"claim": "Reading comprehension is roughly decoding times language comprehension: if either one is missing, the learner cannot understand what they read. Someone who is still learning to decode cannot learn new things by reading text.", "understood": "This is not only about children. Children aged 5–7 are still learning to decode in their first language. Adults learning a new writing system (Chinese characters, kana) are likewise 'not yet able to read' in the target language. So we judge two separate things: can the learner understand the language used for explanation, and can they read the target language's script aloud.", "limits": "The simple view of reading is a model proposed for first-language reading. Applying it to a second language and to non-alphabetic scripts is an extension.", "basis": "literature", "refs": ["ped:simple-view-of-reading", "ped:learning-to-read-vs-reading-to-learn", "ped:young-learner-characteristics"]}, "variables": [{"id": "instructionChannel", "label": "How the task is given", "layer": "block", "values": {"child": "Ages 5–7: sound plus demonstration, with no instruction text on screen. Ages 8–12: one short line of text that can be tapped to hear.", "youth": "Text, one or two sentences, saying what this step practises.", "adult": "Text. If the learner does not yet know the target script well, explanations use the learner's first language or the instruction language they choose."}}, {"id": "scriptAid", "label": "Reading aids such as pinyin or furigana", "layer": "block", "values": {"child": "Only on words the child can already say; remove after the word is read correctly twice.", "youth": "Shown by default and removed word by word; the learner can see how many they have removed.", "adult": "Hidden by default and shown on tap (a tap counts as help); the learner decides when to stop tapping."}}], "measures": [{"label": "Share read correctly on the first try without a reading aid", "source": "block", "how": "attempt events counted separately by whether the aid was showing.", "reads": "Accuracy while the aid stays on does not show that the learner can read."}, {"label": "Items answered correctly only after listening", "source": "block", "how": "Items where read-aloud was tapped before answering are recorded as assisted.", "reads": "Many: the learner understood by ear, not by reading. This is normal while learning to recognise characters, but look at it separately."}]}, {"id": "load", "label": "How much at once, and for how long", "question": "How many things on one screen? How many items in a round? How long is one session?", "answer": {"child": "One thing per screen, 10–15 min", "youth": "One task per screen, 20–30 min", "adult": "Time-boxed, 5–30 min"}, "construct": {"claim": "People can attend to only a limited number of things at once. Younger learners hold attention for a shorter time and are more easily drawn away by things unrelated to the task.", "understood": "We turn this into three quantities that can be counted: how many things on one screen the learner has to deal with, how many items in one round, and how many minutes in one session. The specific numbers are design inference; the literature supports only the direction (fewer and shorter for younger learners).", "limits": "There is no standard for minutes or number of items that can be cited directly. The numbers here are a starting point.", "basis": "design_inference", "refs": ["ped:attention", "ped:young-learner-characteristics", "ped:seductive-details"]}, "variables": [{"id": "perScreen", "label": "Amount per screen", "layer": "block", "values": {"child": "One thing per screen: one picture or one sentence, one place to tap.", "youth": "One task per screen; material and questions can sit side by side.", "adult": "Material, questions and the record can be seen on one screen; secondary parts are collapsed."}}, {"id": "roundSize", "label": "Items per round", "layer": "block", "values": {"child": "3–6 items, with a clear 'all done' at the end.", "youth": "6–10 items, or the learner chooses how many.", "adult": "By time box: 5 minutes or 15 minutes, with the number of items following from that."}}, {"id": "sessionMinutes", "label": "Length of one session", "layer": "plan", "values": {"child": "10–15 minutes, cut into 3–5 short activities that alternate lively and calm.", "youth": "20–30 minutes, one or two tasks.", "adult": "5–30 minutes, split into blocks to fit the time the learner has each day."}}, {"id": "stepsPerItem", "label": "Steps per item, and whether a reason is asked", "layer": "block", "values": {"child": "One step per item: choose only, no reason asked.", "youth": "Two or three steps: choose, then say what it rests on.", "adult": "Two or three steps, including \"why\" and the reasons for ruling out the other options."}}, {"id": "optionCount", "label": "Options at a time", "layer": "block", "values": {"child": "2–3.", "youth": "3–4.", "adult": "4 or more, including \"neither\" and \"both work\"."}}], "measures": [{"label": "Whether accuracy drops during a round", "source": "block", "how": "First-attempt accuracy in the first half versus the second half of the same round.", "reads": "Clearly lower in the second half: the round is too long, so cut items first."}, {"label": "Share of sessions finished and actual duration", "source": "host", "how": "The page does not record duration. The app that hosts it records start, end and any leaving midway.", "reads": "Often unfinished: the session is scheduled too long."}]}, {"id": "pace", "label": "Progress and revisiting", "question": "How much new content per week? How long before coming back to it?", "answer": {"child": "Little new, 30% revisiting", "youth": "25% revisiting", "adult": "More new, 20% revisiting"}, "construct": {"claim": "In classroom conditions, older learners start faster. Younger learners progress more slowly, and their advantage only shows after many years of heavy exposure. Retrieving something again after a gap makes it stick better.", "understood": "So a plan for children is not 'the same content made cuter'. It has less new content each week, more revisiting, and the same content coming back in different activities. A plan for adults can bring in new content more densely, but cannot skip revisiting.", "limits": "How many minutes each knowledge point takes and what share goes to revisiting are planning assumptions. They have not been measured.", "basis": "literature", "refs": ["ped:age-rate-vs-attainment", "ped:age-instructed-settings", "ped:spaced-practice", "ped:retrieval-practice"]}, "variables": [{"id": "minutesPerKc", "label": "Expected time per knowledge point", "layer": "plan", "values": {"child": "About 25 minutes, spread over several days; the content comes in smaller pieces (one chunk, a few words).", "youth": "About 30 minutes.", "adult": "About 30 minutes."}}, {"id": "reviewShare", "label": "Share of the week spent revisiting", "layer": "plan", "values": {"child": "Three tenths: old content comes back inside new activities.", "youth": "Two and a half tenths.", "adult": "Two tenths, with gaps that gradually get longer."}}, {"id": "selection", "label": "Which knowledge points to pick", "layer": "kc", "values": {"child": "The plan picks only what can be heard, said and done in concrete situations; abstract grammar and long reading and writing come later.", "youth": "Priority to what fits the school curriculum, exams and topics of the same age group.", "adult": "Priority to the situations the learner says they need (travel, work, family); the rest is filled in by prerequisite order."}}], "measures": [{"label": "Share answered correctly on the first try after a few days", "source": "host", "how": "The app saves evidence for each knowledge point by date. The first attempt at each revisit is counted separately.", "reads": "Correct on the day but not a few days later: too little revisiting, or the gaps are too long. The page itself does not save across days."}, {"label": "Gap between planned weeks and actual weeks", "source": "host", "how": "Compare the agenda in the blueprint with the actual completion dates.", "reads": "A large gap: the minutesPerKc assumption needs changing."}]}, {"id": "feedback", "label": "How feedback is given", "question": "What does the page say after a wrong answer? Who sees the record of right and wrong?", "answer": {"child": "Show the difference, retry; no crosses", "youth": "Say where it went wrong, retry", "adult": "Name the error type; may skip"}, "construct": {"claim": "Corrective feedback helps. Explicit feedback (pointing out where the mistake is) is more likely to be noticed than just giving the correct answer, but it only works if the learner gets a chance to try again.", "understood": "At every age: immediate, specific, and a second chance. What differs is how detailed it is (pointing out what differs in this attempt, or naming the type of error) and who reads the record.", "limits": "Most feedback research has teens and adults as subjects. The approach for children is design inference.", "basis": "design_inference", "refs": ["ped:corrective-feedback", "ped:noticing-hypothesis"]}, "variables": [{"id": "feedbackForm", "label": "What is said after a wrong answer", "layer": "block", "values": {"child": "Put the correct answer next to the chosen one so the child can see or hear the difference, then try again straight away; no red cross, no points taken off.", "youth": "Point out where the mistake is, give one sentence of reason, then try again; no comparison with others.", "adult": "Name the type of error, with a link to the rule if wanted; skipping is allowed, and the learner can come back later."}}, {"id": "recordAudience", "label": "Who sees the record", "layer": "block", "values": {"child": "For the adult alongside; no score shown to the child.", "youth": "Only for the learner; the learner is told before a teacher sees it.", "adult": "For the learner, with the kinds of items that are still shaky listed by type."}}, {"id": "helpAvailable", "label": "Which help is available", "layer": "block", "values": {"child": "Little and fixed: one or two replays; no timer.", "youth": "Hints can be opened; opening one is recorded as help.", "adult": "Hints, slow speed and captions can be turned on by the learner; using them is recorded as help."}}], "measures": [{"label": "Share wrong on the first try and right on the second", "source": "block", "how": "The first and later attempt events on the same item.", "reads": "High: the feedback was used. Still wrong on the retry: the feedback missed the point, or the item is beyond the current level."}, {"label": "Share correct only after a hint", "source": "block", "how": "Correct attempts with assisted=true.", "reads": "These do not count as independent mastery. If the share stays high over time, step back."}]}, {"id": "autonomy", "label": "Who decides, and why learn this", "question": "Who sets the order and the goal? Should a step say what it is for?", "answer": {"child": "Pick one of two or three; fixed order", "youth": "Own order, purpose stated", "adult": "Own goal and pace"}, "construct": {"claim": "Teenagers are sensitive to being controlled and engage more when they have choices and know the purpose. Adults come with their own goals and experience, want to organise their own learning, and want to use it right away.", "understood": "The range of choice widens with age. Children pick one of two or three options, while the course and the adult keep the order. Teens can set their own order, with the purpose written on each step. Adults set their own goals and pace, and the page makes suggestions rather than rules.", "limits": "These assumptions from adult education come mostly from experience and practice, and the empirical support is weaker than for the entries above.", "basis": "literature", "refs": ["ped:adolescent-motivation-autonomy", "ped:andragogy", "ped:scaffolding"]}, "variables": [{"id": "choice", "label": "What can be chosen", "layer": "block", "values": {"child": "Pick one of two or three themes or characters; the order of steps is fixed, one step at a time.", "youth": "Steps can be done in any order; the learner can choose how many items.", "adult": "The learner chooses which steps to do and for how long, and can jump straight to the parts they are unsure about."}}, {"id": "purposeLine", "label": "Whether to say what a step is for", "layer": "block", "values": {"child": "No purpose is stated; a task in a story leads the way.", "youth": "One line on each step: 'what this step practises'.", "adult": "Each step names the ability being practised and where it is used in real situations."}}, {"id": "goalOwner", "label": "Who sets the goal", "layer": "plan", "values": {"child": "A parent or teacher sets it, and the plan states the goal for the adult to read.", "youth": "Set together with the learner, matched to what school requires.", "adult": "The learner sets it; start with a self-report and begin from the parts they are unsure about."}}], "measures": [{"label": "Which order the learner chose and what they skipped", "source": "block", "how": "Step-switch events.", "reads": "Always skipping the same step: that step is useless to them, or too hard. It is only a record, with no points taken off."}, {"label": "Whether the learner comes back the next day", "source": "host", "how": "Recorded by the app; the page does not know.", "reads": "An indirect signal of motivation. Ask the learner for the reason."}]}, {"id": "mediation", "label": "Who studies alongside, and who judges", "question": "Does someone need to be next to the learner? Who judges whether something said aloud is right?", "answer": {"child": "An adult alongside, who judges", "youth": "With a peer, who judges", "adult": "Alone, against a checklist"}, "construct": {"claim": "When someone beside the child asks questions, takes turns in the talk and helps the child say things in full, the child's language grows better (dialogic reading). Support should be removed once the learner can do it alone.", "understood": "The page does not listen to speech or score pronunciation, so every part where the learner speaks needs a person to judge. For children that is the adult alongside, for teens a peer, and for adults the learner themselves or a language partner. All of these judgments are recorded as self-report and do not count as correct answers.", "limits": "The evidence for dialogic reading comes from first-language shared reading with preschool children. Applying it to a second language and to older children is an extension.", "basis": "literature", "refs": ["ped:dialogic-reading", "ped:scaffolding", "ped:zpd", "ped:negotiated-interaction"]}, "variables": [{"id": "alongside", "label": "Who is nearby", "layer": "plan", "values": {"child": "A parent or teacher; the page gives the adult a line they can say as written.", "youth": "Classmates in pairs, or the learner finishes alone and then swaps with a partner.", "adult": "The learner alone; they can find a language partner, but the page does not depend on someone being there."}}, {"id": "oralJudge", "label": "Who judges what is said aloud", "layer": "block", "values": {"child": "The adult taps 'got it / not yet'.", "youth": "A peer ticks items against a checklist.", "adult": "The learner checks against a checklist or listens back to a recording."}}], "measures": [{"label": "Result of self or peer judgment", "source": "block", "how": "selfReport events, stored separately from attempts.", "reads": "It only says that 'someone thought it was said'. It cannot be used as evidence of mastery, and peers tend to go easy on each other."}]}, {"id": "picture", "label": "What pictures, sound and movement each do", "question": "Are pictures there to bring out the meaning, or only used when words cannot make it clear?", "answer": {"child": "The picture leads; text is short", "youth": "Picture and text side by side", "adult": "A picture only where words fall short"}, "construct": {"claim": "Words paired with a relevant picture are learned better than words alone. Interesting details unrelated to what is being learned reduce learning. Movement and gesture help people remember word meaning.", "understood": "A picture is not decoration. Each picture has one teaching purpose (the eight kinds in image-roles.json). The younger the learner, the more pictures and sound carry; the older, the more pictures retreat to 'where words cannot make it clear'. At any age, nothing unrelated to the task goes in the picture.", "limits": "Most multimedia learning research uses university students learning science content. Applying it to children learning language is an extension.", "basis": "literature", "refs": ["ped:multimedia-learning", "ped:dual-coding", "ped:picture-superiority-vocabulary", "ped:seductive-details", "ped:embodied-gesture-learning", "ped:total-physical-response"]}, "variables": [{"id": "pictureShare", "label": "How much space pictures take and where they go", "layer": "block", "values": {"child": "The picture is the main thing and takes most of the screen; the text is very short and right below the picture.", "youth": "Picture and text sit side by side, the picture takes no more than half, and they can be matched by number.", "adult": "Pictures appear only where words cannot make it clear, placed beside the relevant sentence, and can be tapped to enlarge."}}, {"id": "movement", "label": "Whether to use body movement", "layer": "block", "values": {"child": "Listen and do: stand up, point, pick up, with an adult watching.", "youth": "Drag, place and mark on screen; actually moving only happens in group activities.", "adult": "Operate on screen; movement is used for things that are already tied to the body, such as direction and gesture."}}], "measures": [{"label": "Whether the learner still gets it right with the picture removed", "source": "block", "how": "The reverse half: the same word in a new sentence with no picture, counting first-attempt accuracy.", "reads": "Right with the picture, wrong without: the learner is recognising the picture, not the word."}, {"label": "Whether a generated picture passes the acceptance checklist", "source": "host", "how": "The acceptance checklist that comes with the image instruction, checked item by item by a person.", "reads": "If any one item fails, do not use that picture."}]}, {"id": "reading-mode", "label": "Learning to read, or reading to learn", "question": "Is the goal of this reading to learn to read this script, or to learn new language by reading?", "answer": {"child": "Picture books, read with an adult", "youth": "Illustrated stories for their age", "adult": "Real-life print with pictures"}, "construct": {"claim": "Reading develops in two stages. First learners learn to turn text into words they can already say. Only after that do they use reading to learn what they cannot yet say. Second-language readers need to reach a certain language level before their first-language reading skill can be used.", "understood": "Which kind of reading it is depends on two questions, not on age. Can the learner understand this passage by ear? Can they read this script aloud on their own? Understood by ear but cannot read it aloud: learning to read. Can read it aloud: reading to learn. Both kinds occur at every age. An adult learning Chinese characters or kana is learning to read, and a ten-year-old reading graded English readers can be reading to learn. What age changes is the topic and look of the reading material, whether an adult is present, and how progress is shown.", "limits": "The two-stage account comes from research on first-language reading development. There is no agreed number for where the threshold lies.", "basis": "literature", "refs": ["ped:learning-to-read-vs-reading-to-learn", "ped:simple-view-of-reading", "ped:l2-reading-threshold", "ped:extensive-reading", "ped:dialogic-reading"]}, "variables": [{"id": "material", "label": "What to read", "layer": "plan", "values": {"child": "Picture books: the pictures tell the story, with very short, repetitive text.", "youth": "Short stories or illustrated pieces on topics close to their age group, in a style that is not babyish.", "adult": "Real-life text with pictures: notices, timetables, illustrated instructions, short news reports."}}, {"id": "readingPace", "label": "Pace when learning to read", "layer": "block", "values": {"child": "One sentence per page, an adult points along as the child reads; the same book is read several times.", "youth": "Reads alone and removes the aid word by word; can see which words no longer need the aid.", "adult": "Look at the pattern first (radicals, spelling rules), then recognise it in real text; practise in time boxes."}}, {"id": "progressDisplay", "label": "How progress is shown", "layer": "block", "values": {"child": "Which page they have reached; accuracy is not shown.", "youth": "Learning to read: how many words no longer need the aid. Reading to learn: how many new words were guessed right and which clues were used.", "adult": "Same as for teens, plus a summary by error type."}}], "measures": [{"label": "Learning to read: number of words read correctly with no aid and no picture", "source": "block", "how": "First correct attempts in the reverse half after the aid is removed.", "reads": "Only this counts as 'can read this word'."}, {"label": "Reading to learn: whether guesses at new words are right, and which clues were used", "source": "block", "how": "Word-guessing attempt events plus the clue chosen; for a word the page cannot explain, answering 'this can't be told from here' is the correct answer.", "reads": "Telling 'can be told' from 'cannot be told' matters more than how many guesses were right."}]}, {"id": "use-context", "label": "Where the material comes from, and where it is used", "question": "Whose life do the examples and situations come from? Where will what is learned first be used?", "answer": {"child": "Play, home, stories", "youth": "Friends, school, interests", "adult": "Things they need to get done"}, "construct": {"claim": "Transfer of what is learned to new settings does not happen automatically. The closer the practice setting is to the setting of later use, the easier the transfer. Adult learners have little time and specific goals, and their first language is already set, so they compare with it without meaning to.", "understood": "For the same knowledge point, the example situations differ across the three age bands. For children they come from play, home and stories. For teens they come from peers, school and what they watch. For adults they come from the things they need to get done soon. Adults get one more variable: a comparison with the first language, saying where the two are the same and where the first language will mislead.", "limits": "The choice of situations is design inference. That 'adults are more affected by their first language' has support in the literature, but it varies by language pair.", "basis": "design_inference", "refs": ["ped:transfer", "ped:adult-l2-constraints", "ped:andragogy", "ped:young-learner-characteristics"]}, "variables": [{"id": "exampleContext", "label": "Situation of the examples", "layer": "kc", "values": {"child": "Games, home, animals, characters in stories.", "youth": "Classmates, school, hobbies, things they would meet in short videos and games.", "adult": "Travel, work, seeing a doctor, renting a home, and other settings the learner says they need."}}, {"id": "l1Compare", "label": "Comparison with the first language", "layer": "block", "values": {"child": "No comparison; for heritage-language children, what they already know is not practised again.", "youth": "Point out the one place where the first language most easily misleads.", "adult": "Each pattern has a fixed line beside it comparing with the first language."}}], "measures": [{"label": "Share of transfer items in a new setting answered correctly on the first try", "source": "block", "how": "Transfer items are counted separately from the original items.", "reads": "Right on the original items but wrong on transfer items: the learner only remembered those examples."}, {"label": "Whether the learner says they used it in a real situation", "source": "host", "how": "The app asks every few days; it is self-report.", "reads": "It is only self-report and cannot be used as evidence of mastery."}]}], "blocks": {"picture-book": {"summary": "Both ways of reading work at every age. Children read a picture book; teens and adults read a different story that is not childish and has real print in its pictures. Age changes the material, who is alongside, when the pattern appears, who sets the goal and how the record is worded.", "rows": [{"variable": "material", "child": "The picture book The Blue Paper Boat, 8 pages.", "youth": "The illustrated story The Last Bus, 7 pages, with real print in the pictures (stop sign, timetable, shop notice).", "adult": "The same story, The Last Bus."}, {"variable": "instructionChannel", "child": "Each step's instruction can be played aloud; a separate box gives the adult alongside words to say.", "youth": "Written instruction plus a “Why this step” line.", "adult": "Written instruction stating what the step trains and why it is here."}, {"variable": "choice", "child": "One step at a time, in order.", "youth": "The learner chooses the order of the steps.", "adult": "The learner sets a goal for the unit and a time box of 5, 10 or 15 minutes; a note appears when time is up and nothing is blocked."}, {"variable": "ruleTiming", "child": "No pattern is shown.", "youth": "Shown only after answering, under “The pattern you just used”.", "adult": "The pattern is visible before answering and does not count as a hint; the “Split it up” hint still counts as help."}, {"variable": "l1Compare", "child": "None.", "youth": "None.", "adult": "Each target's pattern comes with one line comparing it to the first language."}, {"variable": "scriptAid", "child": "The reading aid is shown first, withdrawn after two aid-free correct rounds for a word, and restored after a wrong answer.", "youth": "The same fade rule, with a growing list of words now read with no help.", "adult": "The same fade rule; opening the aid is recorded as help."}, {"variable": "oralJudge", "child": "The adult alongside judges the picture walk and the retell.", "youth": "Every step has a “With a classmate” version; the retell is self-rated against a checklist.", "adult": "The retell is self-rated against a checklist."}, {"variable": "recordAudience", "child": "The record is kept under “Record for the adult” and not shown to the child.", "youth": "A record panel sits beside the steps.", "adult": "The record is worded by task as “What this unit got done”, with the goal and the time used."}]}, "space-3d": {"summary": "The same kind of items (how this/that, come/go and front/back/left/right change with viewpoint); age changes the items and how many, the steps per item, when the rule appears, whether feedback uses terms, and who judges the “your turn” step.", "rows": [{"variable": "roundSize", "child": "4 here/there items, 3 come/go, 4 front/back/left/right.", "youth": "7, 5 and 7.", "adult": "7, 5 and 7 (4 come/go items in the Chinese pack)."}, {"variable": "exampleContext", "child": "Bear and Rabbit; an apple, a ball, a tree, a cake.", "youth": "Two peers and family; a phone, a cup, a poster, a brochure, an umbrella, a trip.", "adult": "The same people; also a file, a party invitation (English and Japanese packs), a hotel and a taxi."}, {"variable": "selection", "child": "Front/back items have one reading only (in front of Bear; in front of and behind the tree).", "youth": "Includes “in front of / left of the car”, where two readings are possible.", "adult": "As for youth, plus items such as the hotel entrance that use the thing’s own front only."}, {"variable": "ruleTiming", "child": "No rule panel; the side panel is “for the adult alongside”.", "youth": "The rule panel is empty until the first answer in that kind of item, then the rule appears; front/back adds a line on the two frames of reference.", "adult": "The rule panel is shown from the start."}, {"variable": "l1Compare", "child": "None.", "youth": "None.", "adult": "One comparison sentence, fixed in the language pack, under the rule (the Chinese pack compares with English and Japanese, the English pack with Chinese)."}, {"variable": "instructionChannel", "child": "Each question is read aloud automatically when it appears and every option has a listen button with a speaker icon; the text stays on screen. A separate panel addresses the adult alongside.", "youth": "Text; nothing is read automatically.", "adult": "Text; nothing is read automatically."}, {"variable": "perScreen", "child": "One step per item: choose the word, or click a numbered spot for the ball. On the speaker swap, just choose again.", "youth": "Two or three steps per item: first click who is speaking, then choose the word; on the swap first answer “changes / stays / either”; after a correct placement, “could another spot also be meant?”.", "adult": "Same as youth."}, {"variable": "feedbackForm", "child": "One short sentence without terms (“Look which way Bear’s face points.”); no hint button.", "youth": "Explains whose viewpoint the sentence uses, with the terms “relative frame” and “intrinsic frame”; two or three hint levels that count as help.", "adult": "Same as youth."}, {"variable": "movement", "child": "Front/back only: the adult is told to have the child stand up, turn and do it with their body first; on screen there is one large “Be Bear” button.", "youth": "Turn the scene on screen and look through each person’s eyes.", "adult": "Turn the scene on screen and look through each person’s eyes."}, {"variable": "oralJudge", "child": "Your turn: the child sets up the scene and says it aloud; the adult clicks “said it right / not yet”, recorded as adult-judged.", "youth": "Your turn: type a sentence that the page checks against the scene; it can then be handed to a partner who sets up the scene from the sentence, recorded as partner-judged. Nothing is spoken.", "adult": "Your turn: type two sentences (one for each case), checked by the page against the scene. No one else judges."}, {"variable": "pictureShare", "child": "The scene is 440 px tall.", "youth": "The scene is 380 px tall.", "adult": "The scene is 320 px tall."}, {"variable": "recordAudience", "child": "The record for the three kinds of item sits in a section collapsed by default, “Record for the adult”; the child sees no score.", "youth": "The “Kept separately” card is shown beside the task.", "adult": "The “Kept separately” card is shown beside the task."}]}, "blend": {"summary": "Same words and decoding rules; the child version has shorter rounds, fewer options, and spelling becomes filling one box instead of building the whole word.", "rows": [{"variable": "roundSize", "child": "5 items a round; in the exceptions step, 3 exception words plus 3 regular ones.", "default": "8 items a round; 5 plus 5 in the exceptions step."}, {"variable": "perScreen", "child": "Reading: 3 pictures to choose from. Spelling: one empty box and 3 tiles; tapping a tile is the answer.", "default": "Reading: 4 pictures. Spelling: build the whole word from a bank of tiles, then press Check."}, {"variable": "instructionChannel", "child": "One short line of text (“Tap and read. Which one is it?”); the page does not read it aloud.", "default": "One or two sentences of text saying what to do first and next."}, {"variable": "feedbackForm", "child": "Spelling has one hint (play box by box); no “show the answer” or “clear”.", "default": "Spelling has two hint levels (how many boxes, the tricky box), “show the answer” and “clear”."}, {"variable": "scriptAid", "child": "No IPA when a box is tapped; each box plays for 1.3 s.", "default": "IPA shown when a box is tapped; each box plays for 1 s."}]}, "classifier-match": {"summary": "The child version uses one set with at most 3 boxes, skips “what do the things in this box have in common”, and gives no exceptions among the new items.", "rows": [{"variable": "roundSize", "child": "Sorting: the one set marked for children, at most 3 boxes. New items: 5.", "default": "Sorting: both sets in turn with all their boxes (2–5). New items: 8."}, {"variable": "ruleTiming", "child": "No “what each box has in common” step; the round ends when everything is placed.", "default": "After everything is placed, the learner chooses what each box has in common."}, {"variable": "perScreen", "child": "New items are only ones the rule predicts; no exception, either-works or none-works items.", "default": "At least a quarter of the new items each round are exceptions, either-works or none-works."}, {"variable": "instructionChannel", "child": "One short line: “Tap a thing, then tap its basket.”", "default": "One line of text that also mentions the number keys."}]}, "culture-incident": {"summary": "The child version has a single incident between classmates, three plain kinds of cause, and that step is recorded as discussion rather than right or wrong.", "rows": [{"variable": "exampleContext", "child": "One incident per language pack, set at school between classmates or with a teacher (a cookie, an eraser, how to address the teacher).", "default": "6–7 incidents per pack from adult everyday and work settings."}, {"variable": "metalanguage", "child": "Three kinds of cause: “what was said”, “how it was said”, “nothing was wrong”.", "default": "Five kinds: the words themselves, politeness or address, topic or timing, a missed unspoken meaning, no cultural misunderstanding."}, {"variable": "oralJudge", "child": "Choosing the cause is recorded as a self-report (discussion) and is not tied to the line picked in step 1.", "default": "The page marks the cause right or wrong, and it only counts if the line picked in step 1 was right."}, {"variable": "instructionChannel", "child": "One short line: “From which line does someone start to feel uncomfortable? Click that line.” The click is the answer; no typed explanation and no Submit button.", "default": "Text: click the line, write one sentence of explanation, which is locked on submit."}]}, "entry-sense-pick": {"summary": "The child version only picks the sense, with no reasons or clue word, 4 sentences a round, and no sentences where two senses fit or the word is part of a fixed phrase.", "rows": [{"variable": "roundSize", "child": "4 sentences to look up; 3 notebook entries.", "default": "8 sentences to look up; 5 notebook entries."}, {"variable": "perScreen", "child": "One thing per sentence: pick a sense.", "default": "Three things per sentence: pick a sense, give a reason for ruling out each of the others, and click the clue word in the sentence."}, {"variable": "ruleTiming", "child": "No sentences where two senses both fit or where the word is part of a fixed phrase.", "default": "Every round includes one sentence where two senses fit and one fixed phrase."}]}, "exchange-script": {"summary": "The child version has a single classroom scenario, shows the outcome as faces, and uses plain words for the review categories.", "rows": [{"variable": "exampleContext", "child": "One scenario per pack, all at school (not understanding a word in class, borrowing an eraser, arriving in the morning).", "default": "Six scenarios per pack: rescheduling by phone, ordering, complaining, declining an invitation and so on."}, {"variable": "feedbackForm", "child": "The outcome is two faces: “Did it work?” and “How they feel”; passing just says “You did it!”.", "default": "The outcome is two scales, Task and Relationship, with words; passing explains that the task is done and the relationship is fine."}, {"variable": "metalanguage", "child": "Four review categories in plain words; options always show the actual line.", "default": "Five review categories; options can be shown as the function of each line."}]}, "false-friend-check": {"summary": "The child version has 3 words a round, plain-word verdicts, and no follow-up asking where the meaning shifts.", "rows": [{"variable": "roundSize", "child": "3 words to judge; 3 use items.", "default": "9 words to judge; 6 use items."}, {"variable": "metalanguage", "child": "The three verdicts read “the same 😀”, “a bit different 🤔”, “totally different 😲”.", "default": "The three verdicts read “same”, “shifted”, “different”."}, {"variable": "perScreen", "child": "Choosing “a bit different” completes the judgement.", "default": "After “shifted” the learner must also choose where it shifts (range of meaning, connotation, register, collocation); that choice is scored too."}]}, "figurative-decode": {"summary": "In the English and Chinese packs the child version is a different activity: look at a picture of the words taken literally, then choose the picture of what the speaker means; no irony or hints.", "rows": [{"variable": "pictureShare", "child": "Each item is one sentence plus a picture of its literal meaning; the answers are pictures too (choose one of two).", "default": "No pictures: read a short passage and work out the literal meaning, the gap and the intended meaning in three steps."}, {"variable": "roundSize", "child": "6 items in English, 5 in Chinese.", "default": "15–16 passages."}, {"variable": "selection", "child": "Only metaphors, idioms and literal sentences; irony and hints are also removed from the three-step mode.", "default": "Includes irony, sarcasm and unstated requests."}, {"variable": "feedbackForm", "child": "A wrong choice gets “Listen again and think: could that really happen?” and another try.", "default": "Feedback points out, step by step, the gap between the literal layer and the intended meaning."}]}, "listen-and-do": {"summary": "The child version does 5 simple instructions in the room scene only, with no “don’t…” or “if…” items, at most two replays, and no slow speed or captions.", "rows": [{"variable": "roundSize", "child": "5 instructions a round, room scene only.", "default": "8 in the room, 6 on the street map; the learner can switch scenes."}, {"variable": "selection", "child": "Simple instructions only (the 6 marked for children); no “don’t”, “if…” or “the boy’s left hand” items.", "default": "At least 2 such “do not just act on what you hear” instructions every round."}, {"variable": "feedbackForm", "child": "Two replays; no slow speed and no captions.", "default": "Unlimited replays; slow speed and captions are available and count as help."}, {"variable": "instructionChannel", "child": "The instruction is spoken; the on-screen line is just “Listen and do it.”", "default": "The instruction is spoken; the on-screen text explains pressing Done and that nothing is marked yet."}]}, "number-system-map": {"summary": "The child version switches to 5 cards with numbers up to 10,000 and only 4 magnitude bands.", "rows": [{"variable": "selection", "child": "5 cards with numbers up to 10,000, the number alone (three hundred, two thousand five hundred).", "default": "15–16 cards with numbers up to the hundreds of millions, set in sentences (“this town has 150,000 people”)."}, {"variable": "perScreen", "child": "4 magnitude bands to choose from: 10+, 100+, 1,000+, 10,000+.", "default": "9 magnitude bands, from 100+ to 10,000,000,000+."}]}, "oral-sound-play": {"summary": "The child version has shorter rounds, and sorting becomes a yes-or-no question about one relation.", "rows": [{"variable": "roundSize", "child": "5 words to clap; 4 swaps; 5 sorting items.", "default": "8 words to clap; 6 swaps; 8 sorting items."}, {"variable": "perScreen", "child": "Sorting asks one thing: “Do they rhyme?” (Japanese pack: “same number of beats?”), yes or no.", "default": "Sorting chooses among several relations, and 2 items a round are look-alikes that do not fit."}, {"variable": "instructionChannel", "child": "One short line: “Listen and clap.” The page does not read it aloud.", "default": "One line of text saying whether to clap syllables or phonemes."}]}, "paradigm-apply": {"summary": "In the English pack the child version starts with made-up “wug” words: the child says the form aloud and an adult clicks what was said; in the Japanese and Chinese packs it only has 3 fewer application items.", "rows": [{"variable": "oralJudge", "child": "English pack: the child finishes the sentence aloud and an adult clicks what was said; recorded as partner-judged.", "default": "The learner groups words and fills in forms on screen, and the page marks them."}, {"variable": "ruleTiming", "child": "English pack: no rule first; the rule is tried straight away on made-up words (gutch → ?).", "default": "First group known words by how they change and work out the rule, then apply it."}, {"variable": "roundSize", "child": "4 wug items; 5 application items.", "default": "8 application items (the standard version has no wug tab)."}]}, "picture-talk": {"summary": "Same picture; the child version uses 6 of its elements, describing becomes saying three sentences aloud, and judging is just right or wrong.", "rows": [{"variable": "roundSize", "child": "6 elements of the picture (dog, cat, ducks, children, boy, tree); 9 pointing items; 4 sentences to judge; 4 questions.", "default": "All 14 elements; 16 pointing items; 7 sentences to judge; 9 questions."}, {"variable": "instructionChannel", "child": "No text box for describing: “say three sentences about the picture”, then press “I have said it”.", "default": "Describing means writing 6 to 8 sentences, one per line; “I said it aloud” is an option."}, {"variable": "oralJudge", "child": "The page cannot hear what was said: it is checked afterwards against the picture by the child or a partner.", "default": "Written sentences are checked by the page against the picture’s facts; spoken ones are checked by the learner or a partner."}, {"variable": "metalanguage", "child": "Judging someone’s description is just “right” or “wrong”.", "default": "Judging is a choice of five: correct, wrong position, wrong number, action and state mixed up, cannot be seen in the picture."}]}, "reading-aid-fade": {"summary": "The rule for withdrawing the reading aid is the same in both versions; the child version only has a smaller, easier check after reading.", "rows": [{"variable": "roundSize", "child": "2 words are checked after reading; 4 error-sorting items.", "default": "4 words are checked after reading; 8 error-sorting items."}, {"variable": "perScreen", "child": "Each checked word is a choice between two readings; no typing.", "default": "Each checked word offers all candidate readings, or the reading is typed where the pack supports it."}]}, "reading-select": {"summary": "The child version only chooses the reading and never asks why.", "rows": [{"variable": "ruleTiming", "child": "No reason is asked: each place is just a choice of reading.", "default": "Each place needs the reading and the reason (word class and meaning, fixed word, measure word, must be memorised); the reason is dropped only after the character has been right first time in two contexts."}, {"variable": "roundSize", "child": "5 items in the new-sentence step.", "default": "The whole list in the new-sentence step."}]}, "repair-and-backchannel": {"summary": "The child version has one classroom conversation and three ways to ask for help; choosing one makes the page say a suitable phrase, with no time limit.", "rows": [{"variable": "exampleContext", "child": "One conversation per pack: following a teacher’s craft instructions (paper boats, scissors, crayons).", "default": "Three per pack: buying a ticket at a desk, a group discussion, a phone call and so on."}, {"variable": "choice", "child": "3 moves: ask to repeat, ask to slow down, ask about a word; each with an icon.", "default": "8 moves: also checking by repeating back, showing you are listening, buying time, interrupting politely, bringing the talk back."}, {"variable": "perScreen", "child": "After choosing a move the page says a suitable phrase; the learner does not choose the wording.", "default": "After choosing a move the learner also picks the wording from several phrases."}, {"variable": "feedbackForm", "child": "No time limit; no pause and no “where did I lose it” hint.", "default": "A response time window by default (can be turned off); pause and a “where did I lose it” hint, both counted as help."}]}, "role-marking": {"summary": "The child version has 4 sentences a round, calls the roles “who”, “where”, “where to” and “with whom”, and does not ask why a marker is used.", "rows": [{"variable": "roundSize", "child": "4 items a round (only 4 sentences in each pack are marked for children).", "default": "8 items a round, drawn from about 20 sentences."}, {"variable": "metalanguage", "child": "Roles are called “who”, “where it happens”, “where to”, “with whom”.", "default": "Roles are called “doer”, “who or what is somewhere”, “where it is”, “arrival point”, “companion” and so on."}, {"variable": "ruleTiming", "child": "Choosing the right markers finishes the item; no why question.", "default": "After the markers are right, some items also ask why that marker is used."}, {"variable": "instructionChannel", "child": "One short line: “Look at the picture. Is each one who, where, where to or with whom?”", "default": "One or two sentences: read the sentence, look at the picture, decide the role of each numbered noun."}]}, "sound-contrast": {"summary": "In the English pack the child version uses 5 picture pairs: pictures without spelling, 6 items a round, and after answering it replays both words instead of saying right or wrong; the Japanese and Chinese packs have no child content.", "rows": [{"variable": "pictureShare", "child": "English pack: cards show only a picture (or a number), no spelling or gloss.", "default": "Cards show the spelling, with a picture above it where there is one, and optionally a gloss."}, {"variable": "roundSize", "child": "6 listening items; 6 sorting items.", "default": "12 listening items plus 3 same-or-different items; 9 sorting items."}, {"variable": "feedbackForm", "child": "The same message right or wrong: “It was this one: (picture). Listen to both words once more.” The right card hops, then the words play A-B-A.", "default": "“Right”, or “You heard X, not Y” in red; the two words side by side with the differing letters marked, then A-B-A."}, {"variable": "instructionChannel", "child": "One short line with a “🔊 Instructions” button that reads it aloud in the interface language.", "default": "One line of text including the keyboard shortcut (F / J)."}, {"variable": "ruleTiming", "child": "No articulation note for the contrast.", "default": "A note on the contrast sits beside the task (tongue position, whether the learner’s first language has the sound)."}]}, "story-frames": {"summary": "Same story; the child version has two cards for guessing where the story goes, skips the flashback junction, and asks for fewer connectives and linking devices.", "rows": [{"variable": "perScreen", "child": "Two direction cards when guessing the next picture: “then…” and “but…”.", "default": "Four direction cards: also “so… / in the end…” and “earlier, it turned out…”."}, {"variable": "selection", "child": "The “go back to something earlier” junction is not asked; connectives come from four kinds only: sequence, contrast, flashback, ending.", "default": "The flashback junction is asked too; connectives also include cause, simultaneity and misused distractors."}, {"variable": "roundSize", "child": "A retelling needs 2 kinds of linking device.", "default": "A retelling needs 3 kinds of linking device."}]}, "tone-contour": {"summary": "The child version calls the tones flat road, uphill, valley and downhill, leaves out the half third tone and neutral-tone words, and gives fewer options.", "rows": [{"variable": "metalanguage", "child": "Tones are called flat road, uphill, valley, downhill and small dot; answer buttons carry no pitch numbers.", "default": "Tones are labelled “1st tone 55”, “2nd tone 35”, with the traditional names and descriptions in the legend."}, {"variable": "selection", "child": "No half third tone; no neutral-tone words in listening.", "default": "The half third tone (falling without rising) is taught and tested; listening includes neutral-tone words."}, {"variable": "perScreen", "child": "3 options for a single syllable, 4 tones for words; 2 options for Japanese pitch.", "default": "5 options for listening (four tones plus neutral); 5 for tone-change items (with half third); every possible pattern for Japanese pitch."}, {"variable": "pictureShare", "child": "Large contour drawings have no five-level scale and thicker lines.", "default": "Large contour drawings carry the 1–5 scale."}]}, "variety-map": {"summary": "The child version sorts 6 cards into the varieties only, with no “used everywhere” or “actually an error” columns and no third step.", "rows": [{"variable": "roundSize", "child": "6 cards a round, two steps (recognise, choose for the setting).", "default": "10 cards a round, three steps (also “keep it consistent”)."}, {"variable": "perScreen", "child": "Only the variety columns (for example British, American).", "default": "Two more columns, “used in all varieties” and “error”, with at least one card for each every round."}, {"variable": "instructionChannel", "child": "One short line: “Tap a card, then tap the side it belongs to.”", "default": "Two or three sentences explaining that cards are unlabelled and that some are common to all or are errors."}]}, "viewpoint-direction": {"summary": "The child version only uses home-and-family situations, 2–3 items a round.", "rows": [{"variable": "roundSize", "child": "2–3 placing items a round (all that the packs mark for children); the viewpoint-shift step is skipped (the packs mark no shift items for children) and the page says so in one line.", "default": "8 placing items a round; 6 viewpoint-shift items."}, {"variable": "exampleContext", "child": "Situations are at home: waiting for mum, things between family members.", "default": "Situations involve giving, coming and going, and passives among seniors, friends and others."}, {"variable": "instructionChannel", "child": "One short line: “Put the eye (me) in place, draw the arrow, then pick a word.”", "default": "One or two sentences explaining that the arrow shows who gives to whom, where things move, or who is affected."}]}}}};
